import{c as a,Q as i,j as t,m as s}from"./chunks/framework.DoOjWOm2.js";const g=JSON.parse('{"title":"Passkeys User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"security/passkeys.md","filePath":"security/passkeys.md"}'),o={name:"security/passkeys.md"};function r(n,e,l,c,u,h){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="passkeys-user-guide" tabindex="-1">Passkeys User Guide <a class="header-anchor" href="#passkeys-user-guide" aria-label="Permalink to &quot;Passkeys User Guide&quot;">​</a></h1><p>Passkeys are a modern, passwordless authentication method that uses public-key cryptography to secure your account. They are more secure than passwords and protect against phishing attacks.</p><h2 id="what-is-a-passkey" tabindex="-1">What is a Passkey? <a class="header-anchor" href="#what-is-a-passkey" aria-label="Permalink to &quot;What is a Passkey?&quot;">​</a></h2><p>A passkey is a FIDO2/WebAuthn credential stored on your device or in a hardware security key. It consists of:</p><ul><li><strong>Private key</strong>: Stored securely on your device or hardware key</li><li><strong>Public key</strong>: Stored on the Phlix server</li></ul><p>When you authenticate, the server sends a challenge that your device signs with the private key. The server verifies the signature using the public key.</p><h2 id="benefits" tabindex="-1">Benefits <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;Benefits&quot;">​</a></h2><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong>Phishing-resistant</strong>: Passkeys are bound to the specific domain</li><li><strong>No passwords to steal</strong>: Private keys never leave your device</li><li><strong>Hardware-bound</strong>: Platform authenticators are secured by device security</li><li><strong>Replay protection</strong>: Sign counters detect stolen credential data</li></ul><h3 id="convenience" tabindex="-1">Convenience <a class="header-anchor" href="#convenience" aria-label="Permalink to &quot;Convenience&quot;">​</a></h3><ul><li><strong>No passwords to remember</strong>: Just use your fingerprint, face, or PIN</li><li><strong>Fast login</strong>: One tap or glance to authenticate</li><li><strong>Works everywhere</strong>: Roaming passkeys work on any compatible device</li></ul><h2 id="supported-authenticators" tabindex="-1">Supported Authenticators <a class="header-anchor" href="#supported-authenticators" aria-label="Permalink to &quot;Supported Authenticators&quot;">​</a></h2><h3 id="platform-authenticators" tabindex="-1">Platform Authenticators <a class="header-anchor" href="#platform-authenticators" aria-label="Permalink to &quot;Platform Authenticators&quot;">​</a></h3><ul><li><strong>Touch ID</strong> (macOS)</li><li><strong>Face ID</strong> (iOS/macOS)</li><li><strong>Windows Hello</strong> (Windows)</li><li><strong>Android fingerprints</strong> (Google Pixel, Samsung Galaxy, etc.)</li></ul><h3 id="roaming-authenticators" tabindex="-1">Roaming Authenticators <a class="header-anchor" href="#roaming-authenticators" aria-label="Permalink to &quot;Roaming Authenticators&quot;">​</a></h3><ul><li><strong>YubiKey</strong> (USB-C, USB-A, NFC)</li><li><strong>Solo Key</strong></li><li><strong>Feitian ePass</strong> (NFC)</li><li><strong>Any FIDO2-certified token</strong></li></ul><h2 id="how-to-register-a-passkey" tabindex="-1">How to Register a Passkey <a class="header-anchor" href="#how-to-register-a-passkey" aria-label="Permalink to &quot;How to Register a Passkey&quot;">​</a></h2><ol><li>Log in to Phlix with your existing username and password</li><li>Navigate to <strong>Account Settings</strong> → <strong>Passkeys</strong></li><li>Click <strong>Register New Passkey</strong></li><li>Follow your browser&#39;s prompts to confirm</li><li>Your passkey is now registered and ready to use</li></ol><h2 id="how-to-login-with-a-passkey" tabindex="-1">How to Login with a Passkey <a class="header-anchor" href="#how-to-login-with-a-passkey" aria-label="Permalink to &quot;How to Login with a Passkey&quot;">​</a></h2><h3 id="on-a-device-with-an-existing-passkey" tabindex="-1">On a Device with an Existing Passkey <a class="header-anchor" href="#on-a-device-with-an-existing-passkey" aria-label="Permalink to &quot;On a Device with an Existing Passkey&quot;">​</a></h3><ol><li>Go to the Phlix login page</li><li>Enter your username</li><li>When prompted, use your authenticator (Touch ID, Windows Hello, etc.)</li><li>You&#39;re logged in!</li></ol><h3 id="on-a-new-device" tabindex="-1">On a New Device <a class="header-anchor" href="#on-a-new-device" aria-label="Permalink to &quot;On a New Device&quot;">​</a></h3><p>If you set up a roaming passkey on another device:</p><ol><li>Enter your username on the new device</li><li>Connect your hardware key or use NFC</li><li>Touch the key or confirm with biometrics</li><li>You&#39;re logged in!</li></ol><h2 id="managing-passkeys" tabindex="-1">Managing Passkeys <a class="header-anchor" href="#managing-passkeys" aria-label="Permalink to &quot;Managing Passkeys&quot;">​</a></h2><h3 id="view-registered-passkeys" tabindex="-1">View Registered Passkeys <a class="header-anchor" href="#view-registered-passkeys" aria-label="Permalink to &quot;View Registered Passkeys&quot;">​</a></h3><ol><li>Go to <strong>Account Settings</strong> → <strong>Passkeys</strong></li><li>You&#39;ll see a list of all registered passkeys with: <ul><li>Credential ID (partial)</li><li>Device type (platform or cross-platform)</li><li>Registration date</li></ul></li></ol><h3 id="delete-a-passkey" tabindex="-1">Delete a Passkey <a class="header-anchor" href="#delete-a-passkey" aria-label="Permalink to &quot;Delete a Passkey&quot;">​</a></h3><ol><li>Go to <strong>Account Settings</strong> → <strong>Passkeys</strong></li><li>Click <strong>Delete</strong> next to the passkey you want to remove</li><li>Confirm the deletion</li></ol><p><strong>Warning</strong>: Deleting a passkey is permanent. Make sure you have another login method available before deleting your last passkey.</p><h2 id="multiple-passkeys" tabindex="-1">Multiple Passkeys <a class="header-anchor" href="#multiple-passkeys" aria-label="Permalink to &quot;Multiple Passkeys&quot;">​</a></h2><p>You can register multiple passkeys on a single account. This is useful for:</p><ul><li>Having both a platform authenticator and a hardware key</li><li>Using different devices</li><li>Having backup authenticators</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="no-passkeys-found-during-login" tabindex="-1">&quot;No passkeys found&quot; during login <a class="header-anchor" href="#no-passkeys-found-during-login" aria-label="Permalink to &quot;&quot;No passkeys found&quot; during login&quot;">​</a></h3><ul><li>Make sure you&#39;re using the same account the passkey was registered with</li><li>Check if you&#39;re on the correct website (check the URL)</li><li>Try using a different browser or device</li></ul><h3 id="authenticator-not-registered" tabindex="-1">&quot;Authenticator not registered&quot; <a class="header-anchor" href="#authenticator-not-registered" aria-label="Permalink to &quot;&quot;Authenticator not registered&quot;&quot;">​</a></h3><ul><li>The passkey may have been deleted from your account</li><li>Try registering a new passkey</li></ul><h3 id="fingerprint-face-not-recognized" tabindex="-1">Fingerprint/Face not recognized <a class="header-anchor" href="#fingerprint-face-not-recognized" aria-label="Permalink to &quot;Fingerprint/Face not recognized&quot;">​</a></h3><ul><li>Your device&#39;s biometric data may have changed</li><li>Use your device PIN as a fallback</li><li>Re-register the passkey if needed</li></ul><h3 id="hardware-key-not-detected" tabindex="-1">Hardware key not detected <a class="header-anchor" href="#hardware-key-not-detected" aria-label="Permalink to &quot;Hardware key not detected&quot;">​</a></h3><ul><li>Check that the key is properly connected</li><li>Try a different USB port</li><li>Ensure your browser supports FIDO2/WebAuthn</li><li>Some keys require NFC on mobile devices</li></ul><h2 id="security-best-practices" tabindex="-1">Security Best Practices <a class="header-anchor" href="#security-best-practices" aria-label="Permalink to &quot;Security Best Practices&quot;">​</a></h2><ol><li><strong>Register at least two passkeys</strong> — one as primary and one as backup</li><li><strong>Keep backup codes safe</strong> — store them in a secure location</li><li><strong>Use a hardware key for maximum security</strong> — physical possession required</li><li><strong>Don&#39;t delete your last passkey</strong> — always keep a working login method</li><li><strong>Report suspicious activity</strong> — contact admin if you notice unauthorized access</li></ol><h2 id="platform-specific-notes" tabindex="-1">Platform-Specific Notes <a class="header-anchor" href="#platform-specific-notes" aria-label="Permalink to &quot;Platform-Specific Notes&quot;">​</a></h2><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><ul><li>Safari fully supports passkeys</li><li>Chrome and Firefox also supported</li><li>Touch ID or system password required</li></ul><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ul><li>Windows Hello supported (PIN, fingerprint, face)</li><li>Microsoft Edge recommended for best support</li><li>Chrome and Firefox also supported</li></ul><h3 id="ios-macos-safari" tabindex="-1">iOS/macOS Safari <a class="header-anchor" href="#ios-macos-safari" aria-label="Permalink to &quot;iOS/macOS Safari&quot;">​</a></h3><ul><li>Face ID or Touch ID for authentication</li><li>iCloud Keychain sync available</li><li>Passkeys sync across Apple devices</li></ul><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h3><ul><li>Google Pixel fingerprint/face unlock</li><li>Chrome supported</li><li>May sync via Google Password Manager</li></ul><h3 id="hardware-keys" tabindex="-1">Hardware Keys <a class="header-anchor" href="#hardware-keys" aria-label="Permalink to &quot;Hardware Keys&quot;">​</a></h3><ul><li>YubiKey 5 series recommended</li><li>Store backup keys in a secure location</li><li>Some services support only certain key models</li></ul>',55)])])}const y=a(o,[["render",r]]);export{g as __pageData,y as default};
